const fila = $('Buscar Fila').all().map(i => i.json).filter(x => x && x.tipo);
const cfg = ($json && $json.valor) ? $json.valor : {};
const teto = cfg.teto_email_dia ?? 20;

const enc = fila.filter(x => x.tipo === 'encerrar_silencio');
const cp  = fila.filter(x => x.tipo === 'conversa_parada_auto')
  .sort((a,b) => new Date(a.devido_em) - new Date(b.devido_em));
// conversa_parada (agendado pelo agente A2 ou manual): o ramo da view devolve
// TODOS os pendentes, inclusive futuros — filtrar por vencimento aqui
const cpm = fila.filter(x => x.tipo === 'conversa_parada'
    && new Date(x.devido_em) <= new Date())
  .sort((a,b) => new Date(a.devido_em) - new Date(b.devido_em));
// PREVIA: sem este filtro os tipos novos sumiam aqui — o return monta a saida
// a partir de listas nomeadas, entao tipo que ninguem coleta e descartado calado.
const pv = fila.filter(x => ['previa_d2', 'previa_d5', 'previa_d7_expira', 'reenvio_pos_bot'].includes(x.tipo)
    && new Date(x.devido_em) <= new Date())
  .sort((a, b) => new Date(a.devido_em) - new Date(b.devido_em));

const f2  = fila.filter(x => x.tipo === 'f2_breakup')
  .sort((a,b) => new Date(a.devido_em) - new Date(b.devido_em));
const f1  = fila.filter(x => x.tipo === 'f1_email')
  .sort((a,b) => new Date(a.devido_em) - new Date(b.devido_em))
  .slice(0, teto);

// pos_checkout segue fora do W3 (sem consumidor por enquanto)
return [...enc, ...pv, ...cp, ...cpm, ...f2, ...f1].map(json => ({ json }));

const item = $('Loop').item.json;   // item da fila (tipo, slug, devido_em, email...)
const emp = $json;                    // dossiê (HTTP desembrulha item único)
const inter = Array.isArray(emp.interacoes) ? emp.interacoes : [];

const msg1 = inter
  .filter(i => i.etapa === 'msg1' && i.direcao === 'saida')
  .sort((a,b) => new Date(a.criado_em) - new Date(b.criado_em))[0];
const f1ant = inter.filter(i => i.etapa === 'f1_email')[0];
const ultimaResposta = inter
  .filter(i => i.etapa === 'resposta_agente' && i.direcao === 'saida')
  .sort((a,b) => new Date(b.criado_em) - new Date(a.criado_em))[0];
const ultimaEntrada = inter
  .filter(i => i.direcao === 'entrada')
  .sort((a,b) => new Date(b.criado_em) - new Date(a.criado_em))[0];

const nome = emp.nome_fantasia || emp.nome || emp.razao_social || item.slug;
const cidade = emp.cidade || emp.municipio || '';
const perfil = emp.perfil_oferta || emp.classificacao_oferta || '';

// AJUSTE SE NECESSÁRIO: coluna do número validado usada pelo A2 Disparo
const numeroWhats = emp.whatsapp || emp.celular_whatsapp || emp.celular || emp.telefone || null;

let system, prompt;

const TIPOS_PREVIA = ['previa_d2', 'previa_d5', 'reenvio_pos_bot'];

if (TIPOS_PREVIA.includes(item.tipo)) {
  // O A2 Disparo gravou a URL da previa em followups_agendados.contexto.
  const urlPrevia = String(item.contexto || emp.previa_url || '').replace(/^https?:\/\//, '');
  const expira = emp.previa_expira_em
    ? new Date(emp.previa_expira_em)
    : new Date(new Date(item.devido_em).getTime() + 2 * 864e5);
  const diaSemana = expira.toLocaleDateString('pt-BR', { weekday: 'long', timeZone: 'America/Sao_Paulo' });

  const COMUM = `Você é Thyago, da Somos Atitude. Escreve no WhatsApp, em português brasileiro, tom profissional e caloroso.

RETORNE SOMENTE JSON válido, sem markdown, no formato: {"mensagem": "..."}

REGRAS INVIOLÁVEIS:
- Entre 100 e 400 caracteres. Uma mensagem só, sem quebrar em balões.
- Sem ponto de exclamação, sem travessão, sem a pergunta "faz sentido?", sem emoji.
- Nenhum link além do endereço da própria prévia, quando o tipo permitir.
- Nunca invente número, prazo ou resultado que não esteja neste briefing.`;

  if (item.tipo === 'previa_d2') {
    system = COMUM + `

TIPO: previa_d2. O lead recebeu o endereço da prévia há 2 dias e ABRIU a página.
- Objetivo: puxar a opinião dele. Pergunte se chegou a ver e o que mudaria.
- PROIBIDO falar preço, valor, plano ou qualquer número de dinheiro.
- Não repita a msg1 nem descreva de novo o que tem na página.`;
    prompt = `Empresa: ${nome}${cidade ? ' — ' + cidade : ''}
Prévia: ${urlPrevia}
Msg1 já enviada: "${msg1 ? msg1.mensagem : 'n/d'}"

Gere o follow-up D2 agora.`;
  } else if (item.tipo === 'previa_d5') {
    system = COMUM + `

TIPO: previa_d5. A prévia sai do ar em ${diaSemana}, e a data é real.
- AQUI o preço é permitido: "R$599 em 3x ou Pix, e eu já migro pro seu domínio".
- Diga quando sai do ar sem ameaçar e sem inventar urgência além da data real.
- Nada de desconto e nada de cupom.`;
    prompt = `Empresa: ${nome}${cidade ? ' — ' + cidade : ''}
Prévia: ${urlPrevia}
Sai do ar: ${diaSemana}
Msg1 já enviada: "${msg1 ? msg1.mensagem : 'n/d'}"

Gere o follow-up D5 agora.`;
  } else {
    system = COMUM + `

TIPO: reenvio_pos_bot. Um atendente automático respondeu no lugar da pessoa, e a msg1 não chegou a quem decide.
- Devolva EXATAMENTE o texto da msg1 abaixo, sem reescrever, sem cumprimentar de novo, sem acrescentar nada.
- Se a msg1 vier vazia, devolva mensagem vazia.`;
    prompt = `Msg1 original, para reenviar sem alteração:
"${msg1 ? msg1.mensagem : ''}"`;
  }
} else if (item.tipo === 'f1_email') {
  system = `Você é Thyago, fundador da Somos Atitude (agência digital de Goiânia que cria sites e presença no Google para clínicas e profissionais de saúde/estética). Você escreve e-mails de follow-up curtos, pessoais e consultivos — nunca com cara de mala direta.\n\nRETORNE SOMENTE JSON válido, sem markdown, no formato: {\"assunto\": \"...\", \"corpo\": \"...\"}\n\nREGRAS INVIOLÁVEIS:\n- assunto: máx. 60 caracteres, específico ao negócio, sem CAPS, sem exclamações duplas, sem palavras como grátis, promoção, imperdível, oferta\n- corpo: texto puro, UM parágrafo principal de valor + fecho curto. Abre referenciando a mensagem de WhatsApp já enviada (\"te mandei uma mensagem no WhatsApp essa semana sobre...\"). Traz UM diagnóstico consultivo real do negócio (presença no Google, site, busca local) — espelho, não pitch. NUNCA repete o argumento da msg1: usa um ângulo novo.\n- SEM nenhum link ou URL no corpo. CTA em texto puro: \"é só me chamar no WhatsApp (62) 98195-0604\" — e responder este e-mail também funciona\n- Assinatura ao final, em linhas separadas: \"Thyago — Somos Atitude\" e \"somosatitude.com.br\"\n- Sem preço, sem cupom, sem anexo, sem emoji\n- Tom: brasileiro natural, direto, respeitoso do tempo da pessoa`;
  const aviso = item.email_contab ? '\nATENÇÃO: este e-mail pode ser do contador da empresa. Abra o corpo com: se você cuida da ' + nome + ' ou puder encaminhar ao responsável, agradeço.' : '';
  prompt = `Empresa: ${nome}${cidade ? ' — ' + cidade : ''}\nPerfil de oferta: ${perfil || 'não classificado'}\n\nMensagem 1 enviada no WhatsApp (para referenciar SEM repetir o argumento):\n\"${msg1 ? msg1.mensagem : '(não localizada — referencie genericamente uma mensagem enviada no WhatsApp essa semana)'}\"${aviso}\n\nGere o e-mail F1 agora.`;

} else if (item.tipo === 'conversa_parada_auto') {
  system = `Você é Thyago, da Somos Atitude. O lead veio de um anúncio, você respondeu no WhatsApp, e ele não retornou. Escreva um lembrete curto pra retomar EXATAMENTE de onde parou — leia a sua última mensagem com atenção e identifique o que ficou pendente (pode ser uma venda com CTA, ou uma coleta de dados como nome/cidade do negócio).\n\nRETORNE SOMENTE JSON válido, sem markdown: {\"mensagem\": \"...\"}\n\nREGRAS:\n- Curta: 1 a 3 frases, entre 60 e 250 caracteres\n- Se a última mensagem pedia uma AÇÃO do lead (confirmar compra, responder uma pergunta, mandar um dado) — retome exatamente essa ação pendente, sem reexplicar tudo de novo\n- Tom leve, direto, sem pressão — como quem só está checando se a pessoa viu a mensagem\n- NUNCA invente uma oferta ou informação que não estava na mensagem original\n- Sem link, sem emoji ou no máximo um`;
