let linha = null;
try {
  const r = $('Revalidar Contato').item.json;
  linha = Array.isArray(r) ? r[0] : r;
} catch (e) { linha = null; }

let permitido = null;
if (linha && typeof linha.fn_contato_permitido === 'boolean') {
  permitido = linha.fn_contato_permitido;
}

let enviar = false, motivo = null;

if (permitido !== true) {
  motivo = (permitido === false)
    ? 'BLOQUEADO: contato nao permitido agora (opt_out / atendimento_humano / bot_suspeito / status)'
    : 'BLOQUEADO: revalidacao indeterminada — fail-closed, nao envia';
} else {
  enviar = true;
}

return [{ json: {
