  prompt = `Empresa: ${nome}${cidade ? ' — ' + cidade : ''}\nPerfil de oferta: ${perfil || 'não classificado'}\n\nMensagem 1 enviada no WhatsApp (para referenciar SEM repetir o argumento):\n\"${msg1 ? msg1.mensagem : '(não localizada — referencie genericamente uma mensagem enviada no WhatsApp essa semana)'}\"${aviso}\n\nGere o e-mail F1 agora.`;

