  prompt = `Lead (via anúncio): ${nome}\n\nSua última mensagem enviada (que ficou sem resposta):\n\"${ultimaResposta ? ultimaResposta.mensagem : 'n/d'}\"\n\nGere o lembrete de retomada agora, identificando e reabrindo o que ficou pendente nessa mensagem.`;

